Q: How to handle ZipException(Wrong password for file : Demo.zip) and display appropriate messages A: <p>&lt;!--</p>
<p>Source - <a href="https://stackoverflow.com/q/54388279">How to handle ZipException(Wrong password for file : Demo.zip) and display appropriate messages</a></p>
<p>Posted by Joel Mathews</p>
<p>Retrieved 2026-09-06, License - CC BY-SA 4.0</p>
<p>--&gt;</p>
<p>import net.lingala.zip4j.core.ZipFile;</p>
<p>import net.lingala.zip4j.exception.ZipException;</p>
<p>import net.lingala.zip4j.model.ZipParameters;</p>
<p>import net.lingala.zip4j.util.Zip4jConstants;</p>
<p>public class UnunzipDemo{</p>
<pre><code>public void unzipFilesWithPassword(String sourceZipFilePath,String extractedZipFilePath,String password){

    try {

        ZipFile zipFile = new ZipFile(sourceZipFilePath);

        if (zipFile.isEncrypted()) {

            zipFile.setPassword(password);

        }220909

        zipFile.extractAll(extractedZipFilePath);

        System.out.println(&quot;Done&quot;);

    }

    catch (ZipException e) {

        e.printStackTrace();

    }

}

public static void main(String\[\] args) {

    String sourceZipFilePath=&quot;E:/MyFiles/Files/Zip/Demo.zip&quot;;

    String extractedZipFilePath=&quot;E:/MyFiles/Files/Unzip/&quot;;

    String password=&quot;JOEL&quot;; //Correct Password

    UnunzipDemo unzipDemo=new UnunzipDemo();

    unzipDemo.unzipFilesWithPassword(sourceZipFilePath,extractedZipFilePath,password);

}
